<?php
require_once __DIR__.'/includes/email.php';email_require('providers');$pageTitle='سرویس‌دهندگان ایمیل';
if($_SERVER['REQUEST_METHOD']==='POST'){if(!Auth::verifyCsrf($_POST['csrf_token']??'')){flash('اعتبار درخواست منقضی شده است.','danger');redirect('/admin/email-providers.php');}try{$id=(int)($_POST['id']??0);$name=trim((string)($_POST['name']??''));$code=strtolower(trim((string)($_POST['code']??'')));if($name===''||!preg_match('/^[a-z0-9_-]{2,100}$/',$code))throw new InvalidArgumentException('نام و کد معتبر سرویس‌دهنده الزامی است.');$json=trim((string)($_POST['oauth_config_json']??''));if($json!==''&&json_decode($json,true)===null)throw new InvalidArgumentException('تنظیمات OAuth باید JSON معتبر باشد.');$data=[$name,$code,in_array($_POST['provider_type']??'',['gmail','yahoo','website','custom'],true)?$_POST['provider_type']:'custom',trim((string)($_POST['imap_host']??'')),max(1,min(65535,(int)($_POST['imap_port']??993))),in_array($_POST['imap_encryption']??'',['ssl','tls','none'],true)?$_POST['imap_encryption']:'ssl',trim((string)($_POST['smtp_host']??'')),max(1,min(65535,(int)($_POST['smtp_port']??587))),in_array($_POST['smtp_encryption']??'',['ssl','tls','none'],true)?$_POST['smtp_encryption']:'tls',in_array($_POST['auth_type']??'',['password','app_password','oauth2'],true)?$_POST['auth_type']:'password',$json?:null,isset($_POST['active'])?1:0];if($id)Database::execute('UPDATE email_providers SET name=?,code=?,provider_type=?,imap_host=?,imap_port=?,imap_encryption=?,smtp_host=?,smtp_port=?,smtp_encryption=?,auth_type=?,oauth_config_json=?,active=?,updated_at=NOW() WHERE id=?',[...$data,$id]);else Database::execute('INSERT INTO email_providers(name,code,provider_type,imap_host,imap_port,imap_encryption,smtp_host,smtp_port,smtp_encryption,auth_type,oauth_config_json,active,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,NOW(),NOW())',$data);EmailHubModule::log(null,null,'provider_saved','سرویس‌دهنده ایمیل ذخیره شد.',null,['provider_id'=>$id?:Database::lastInsertId()]);flash('سرویس‌دهنده ایمیل ذخیره شد.');}catch(InvalidArgumentException $e){flash($e->getMessage(),'danger');}catch(Throwable $e){flash(email_safe_error($e,'ذخیره سرویس‌دهنده انجام نشد.'),'danger');}redirect('/admin/email-providers.php');}
$edit=isset($_GET['edit'])?Database::fetch('SELECT * FROM email_providers WHERE id=?',[(int)$_GET['edit']]):null;$providers=Database::fetchAll('SELECT p.*,(SELECT COUNT(*) FROM email_accounts a WHERE a.provider_id=p.id) account_count FROM email_providers p ORDER BY p.active DESC,p.name');require __DIR__.'/../views/partials/admin-header.php';?>
<div class="email-page-head"><div><h1>سرویس‌دهندگان ایمیل</h1><p>Gmail، Yahoo، ایمیل هاست و هر سرویس استاندارد IMAP/SMTP</p></div><a class="btn" href="/admin/email-accounts.php">حساب‌ها</a></div><?php email_tabs('providers')?>
<section class="card email-form-card"><h2><?=$edit?'ویرایش سرویس‌دهنده':'سرویس‌دهنده جدید'?></h2><form method="post"><input type="hidden" name="csrf_token" value="<?=e(Auth::csrfToken())?>"><input type="hidden" name="id" value="<?=e($edit['id']??'')?>"><div class="grid grid-3"><label class="form-field"><span>نام</span><input name="name" required value="<?=e($edit['name']??'')?>"></label><label class="form-field"><span>کد انگلیسی</span><input name="code" required pattern="[a-z0-9_-]+" value="<?=e($edit['code']??'')?>"></label><label class="form-field"><span>نوع</span><select name="provider_type"><?php foreach(['gmail'=>'Gmail','yahoo'=>'Yahoo','website'=>'ایمیل هاست','custom'=>'سفارشی'] as $v=>$l):?><option value="<?=$v?>" <?=($edit['provider_type']??'custom')===$v?'selected':''?>><?=$l?></option><?php endforeach?></select></label><label class="form-field"><span>IMAP Host</span><input name="imap_host" dir="ltr" value="<?=e($edit['imap_host']??'')?>"></label><label class="form-field"><span>IMAP Port</span><input type="number" name="imap_port" value="<?=e($edit['imap_port']??'993')?>"></label><label class="form-field"><span>رمزنگاری IMAP</span><select name="imap_encryption"><?php foreach(['ssl'=>'SSL','tls'=>'STARTTLS','none'=>'بدون رمزنگاری'] as $v=>$l):?><option value="<?=$v?>" <?=($edit['imap_encryption']??'ssl')===$v?'selected':''?>><?=$l?></option><?php endforeach?></select></label><label class="form-field"><span>SMTP Host</span><input name="smtp_host" dir="ltr" value="<?=e($edit['smtp_host']??'')?>"></label><label class="form-field"><span>SMTP Port</span><input type="number" name="smtp_port" value="<?=e($edit['smtp_port']??'587')?>"></label><label class="form-field"><span>رمزنگاری SMTP</span><select name="smtp_encryption"><?php foreach(['ssl'=>'SSL','tls'=>'STARTTLS','none'=>'بدون رمزنگاری'] as $v=>$l):?><option value="<?=$v?>" <?=($edit['smtp_encryption']??'tls')===$v?'selected':''?>><?=$l?></option><?php endforeach?></select></label><label class="form-field"><span>نوع احراز هویت</span><select name="auth_type"><?php foreach(['password'=>'رمز عبور','app_password'=>'App Password','oauth2'=>'OAuth2'] as $v=>$l):?><option value="<?=$v?>" <?=($edit['auth_type']??'password')===$v?'selected':''?>><?=$l?></option><?php endforeach?></select></label><label class="form-field grid-span-2"><span>تنظیمات OAuth JSON (اختیاری)</span><textarea name="oauth_config_json" dir="ltr"><?=e($edit['oauth_config_json']??'')?></textarea></label><label class="checkbox-item"><input type="checkbox" name="active" <?=!isset($edit['active'])||(int)$edit['active']?'checked':''?>> فعال</label></div><div class="form-actions"><button class="btn btn-primary">ذخیره سرویس‌دهنده</button><?php if($edit):?><a class="btn" href="/admin/email-providers.php">انصراف</a><?php endif?></div></form></section>
<section class="card"><div class="table-wrap"><table><thead><tr><th>سرویس‌دهنده</th><th>IMAP</th><th>SMTP</th><th>احراز هویت</th><th>حساب‌ها</th><th>وضعیت</th><th></th></tr></thead><tbody><?php foreach($providers as $p):?><tr><td><strong><?=e($p['name'])?></strong><small><?=e($p['code'])?></small></td><td dir="ltr"><?=e($p['imap_host'].':'.$p['imap_port'].' / '.$p['imap_encryption'])?></td><td dir="ltr"><?=e($p['smtp_host'].':'.$p['smtp_port'].' / '.$p['smtp_encryption'])?></td><td><?=e(['password'=>'رمز عبور','app_password'=>'App Password','oauth2'=>'OAuth2'][$p['auth_type']]??'')?></td><td><?=e((string)$p['account_count'])?></td><td><?=$p['active']?'فعال':'غیرفعال'?></td><td><a class="btn btn-small" href="?edit=<?=$p['id']?>">ویرایش</a></td></tr><?php endforeach?></tbody></table></div></section><?php require __DIR__.'/../views/partials/admin-footer.php';?>
